components.css:
.ds-letter-preview{--sign-depth:14px;--sign-contrast:#eee7d5;--sign-face:#355e3c;--sign-edge:#203b27;--sign-light:#c3ecbc;font-family:var(--font-archivo,Archivo),sans-serif;height:280px;background:#bfc1b2;background-image:radial-gradient(ellipse at 35% 20%,#e6e5d2b3,transparent 70%);position:relative;display:grid;place-items:center;overflow:hidden;container-type:inline-size;perspective:900px}.ds-letter-preview::after{content:"";position:absolute;inset:0;pointer-events:none;box-shadow:inset 0 -35px 65px #484f4320}.ds-letter-object { display: grid; place-items: center; transform-style: preserve-3d; transform: rotateX(6deg) rotateY(-12deg); transition: transform .6s cubic-bezier(.16, 1, .3, 1); white-space: nowrap; font-size: min(17cqw, 104px); line-height: 1.5; }
.ds-rotated { transform: rotateX(-7deg) rotateY(34deg); }
.ds-letter-layer, .ds-letter-face, .ds-letter-glow, .ds-letter-diffuser { grid-area: 1 / 1; display: block; backface-visibility: hidden; }
.ds-letter-layer { color: var(--sign-edge); transform: translateZ(calc(var(--layer) * var(--sign-depth))); }
.ds-letter-layer[data-translucent="true"] { color: var(--sign-light); }
.ds-letter-layer:nth-child(2) { text-shadow: 8px 13px 10px #121b1460; }
.ds-letter-face { color: var(--sign-face); transform: translateZ(calc(var(--sign-depth) + .8px)); text-shadow: 0 1px 1px #ffffff60; -webkit-text-stroke: .35px #ffffff28; }
.ds-letter-diffuser { visibility: hidden; color: var(--sign-light); transform: translateZ(calc(var(--sign-depth) + .4px)); }
.ds-letter-glow { color: transparent; transform: translateZ(-4px); }
.ds-night.ds-volume .ds-letter-face { filter: brightness(1.25); }
.ds-halo .ds-letter-glow, .ds-dupla .ds-letter-glow { color: var(--sign-light); text-shadow: 0 0 10px var(--sign-light), 0 0 25px var(--sign-light), 0 0 45px color-mix(in srgb, var(--sign-light), transparent 40%); filter: blur(5px); }
.ds-halo .ds-letter-face { color: var(--sign-face); }
.ds-frontal .ds-letter-face, .ds-dupla .ds-letter-face, .ds-total .ds-letter-face { color: var(--sign-light); text-shadow: 0 0 6px var(--sign-light), 0 0 22px color-mix(in srgb, var(--sign-light), transparent 65%); -webkit-text-stroke: .6px var(--sign-face); }
.ds-neon .ds-letter-layer { color: transparent; -webkit-text-stroke: 1.4px var(--sign-edge); }
.ds-neon .ds-letter-face { color: transparent; -webkit-text-stroke: 1.5px var(--sign-light); text-shadow: none; filter: drop-shadow(0 0 2px var(--sign-light)) drop-shadow(0 0 7px var(--sign-light)); }
.ds-lateral .ds-letter-layer[data-translucent="true"], .ds-total .ds-letter-layer[data-translucent="true"] { text-shadow: 0 0 2px color-mix(in srgb, var(--sign-light), transparent 60%); }
.ds-perfurado .ds-letter-diffuser, .ds-ripado .ds-letter-diffuser, .ds-recuado .ds-letter-diffuser { visibility: visible; text-shadow: 0 0 6px color-mix(in srgb, var(--sign-light), transparent 45%); }
/* Masks depict actual apertures in an opaque face, with a diffuser behind it. */
.ds-perfurado .ds-letter-face { mask-image: radial-gradient(circle at center, transparent 1.5px, #000 1.8px); mask-size: 6px 6px; -webkit-text-stroke: 0; text-shadow: none; }
.ds-ripado .ds-letter-face { mask-image: repeating-linear-gradient(90deg, #000 0 5px, transparent 5px 7px); -webkit-text-stroke: 0; text-shadow: none; }
.ds-recuado .ds-letter-layer { color: transparent; -webkit-text-stroke: .018em var(--sign-edge); }
.ds-recuado .ds-letter-face { color: transparent; -webkit-text-stroke: .018em var(--sign-face); text-shadow: none; transform: translateZ(calc(var(--sign-depth) + 3px)); }
.ds-recuado .ds-letter-diffuser { transform: translateZ(calc(var(--sign-depth) - 4px)); }
.ds-bicolor .ds-letter-layer { color: var(--sign-contrast); }
.ds-borda .ds-letter-face { -webkit-text-stroke: .028em var(--sign-contrast); paint-order: stroke fill; text-shadow: 1px 2px 2px #00000050; }

.ds-atmosphere-surface{position:relative;overflow:hidden;background:#171b16;max-width:650px}.ds-atmosphere {
  --cursor-x: 0;
  --cursor-y: 0;
  position: absolute;
  inset: 0;
  pointer-events: none;
  user-select: none;
}
.ds-piece {
  --travel-x: 20px;
  --travel-y: 14px;
  --angle: 0deg;
  position: absolute;
  transform: translate3d(calc(var(--cursor-x) * var(--travel-x)), calc(var(--cursor-y) * var(--travel-y)), 0) rotate(var(--angle));
  transition: transform 700ms cubic-bezier(.16, 1, .3, 1);
}
.ds-lightTube {
  overflow: visible;
  stroke: #e5f6d5;
  stroke-width: 3;
  stroke-linecap: round;
  stroke-linejoin: round;
  filter: drop-shadow(0 0 3px #74c365) drop-shadow(0 0 9px #74c36580);
}
.ds-neon {
  position: relative;
  min-width: 0;
  min-height: 620px;
  isolation: isolate;
  background: radial-gradient(ellipse at 42% 48%, #3e53312b, transparent 68%);
}
.ds-neonArch { width: 48%; max-width: 330px; left: 11%; top: 9%; --angle: -17deg; --travel-x: -22px; --travel-y: -16px; }
.ds-neonArch svg { display: block; width: 100%; stroke: #91ce79; stroke-width: 2; filter: drop-shadow(0 0 3px #74c36580) drop-shadow(0 0 14px #74c36550); }
.ds-neonMonogram { width: 44%; max-width: 290px; left: 33%; top: 17%; --angle: 12deg; --travel-x: 32px; --travel-y: 20px; }
.ds-neonMonogram svg { display: block; width: 100%; stroke-width: 3.5; filter: drop-shadow(0 0 2px #74c365) drop-shadow(0 0 10px #74c365b3) drop-shadow(0 9px 22px #74c36535); }
.ds-neonScript { left: 22%; bottom: 8%; font-family: var(--font-sign-script,Satisfy), cursive; font-size: clamp(150px, 17vw, 250px); line-height: 1; color: #f2ead6; text-shadow: 0 0 3px #e5ca8d, 0 0 15px #c2a36a90, 0 9px 32px #c2a36a30; --angle: -14deg; --travel-x: -28px; --travel-y: 22px; }
.ds-neonSpark { width: 17%; max-width: 105px; right: 10%; bottom: 19%; --angle: 18deg; --travel-x: 24px; --travel-y: -20px; }
@media(max-width:760px){.ds-neon{min-height:360px;max-width:520px;width:100%;margin-inline:auto}.ds-neonArch{width:40%;left:12%;top:9%}.ds-neonMonogram{width:40%;left:39%;top:12%}.ds-neonScript{font-size:160px;bottom:6%;left:23%}.ds-neonSpark{width:15%;right:10%;bottom:13%}}
@media(max-width:380px){.ds-neon{min-height:320px}.ds-neonScript{font-size:140px}}
@media(hover:none),(pointer:coarse),(prefers-reduced-motion:reduce){.ds-piece{transform:rotate(var(--angle));transition:none}}
@media print{.ds-atmosphere{display:none}}
